        headers,
        json: true,
        timeout: 5000,
      });
      activeSystemPrompt = String(Array.isArray(promptRows) ? promptRows[0]?.prompt || '' : '').trim();
      if (!activeSystemPrompt) activeSystemPrompt = String(tenantSettings.system_prompt || '').trim();
