  || serviceCategories.some((item) => ['aneis', 'pulseiras', 'cordoes', 'pedras', 'joias', 'prata'].includes(item));
if (commerceMode && service === 'comercial' && !hasAny(value, ['orcamento', 'proposta', 'contrato'])) {
  service = 'catalogo_produtos';
  stage = 'Qualificacao';
  handoff = false;
}
