    ?inventory.map(row=>{const {canonical_price_cents,...safe}=row;return safe;}):inventory;
  // Document text is not sent to the commercial model; OCR has a separate private store.
  const safeMessages=messages.map(m=>({...m,text:salesRedactPersonalData(m.text)}));
  const referral=salesReferralForTurn(history,turn.messages,context);
  const currentTurnText=turn.messages.map(message=>message?.text||'').join(' ');
  const referralMatch=referral?salesReferralProduct(referral,inventory,currentTurnText):null;
  const recentCatalog=salesRecentCatalogContext(history,inventory);
  const contextualReference=salesCatalogChoice(history,turn.messages,inventory);
  const referralFacts=referral?{context:{source:referral.source,title:referral.title,body:referral.body,media_type:referral.media_type},
    inventory_match:referralMatch?.product?{status:'unique',vehicle:{name:referralMatch.product.name,model:referralMatch.product.model,
      year:referralMatch.product.year,color:referralMatch.product.color,price_cents:referralMatch.product.price_cents}}
      : {status:referralMatch?.candidates?.length?'ambiguous':'not_found'}}:null;
  markUsage();
  const body=await httpJson('POST','https://generativelanguage.googleapis.com/v1beta/models/'+model+':generateContent',
    {'Content-Type':'application/json','x-goog-api-key':env('GEMINI_API_KEY')},
    {system_instruction:{parts:[{text:settings.system_prompt+["","","REGRAS DE INTERPRETACAO CONVERSACIONAL","- Clientes de WhatsApp podem escrever com erros, abreviacoes, girias, concordancia ruim e palavras digitadas no tempo verbal errado. Use o contexto antes de interpretar literalmente.","- Se duas interpretacoes plausiveis mudarem produto, intencao, venda/troca, pagamento ou etapa comercial, NAO chute: faca uma unica pergunta curta de confirmacao antes de alterar o estado.","- Uma correcao ou pergunta direta da mensagem atual tem prioridade sobre uma pergunta pendente anterior. Nunca ignore uma pergunta atual apenas para repetir um campo pendente.","- PRECO: quando price_cents for null, nao informe valor da planilha nem invente precos. Quando houver valor, use price_cents/customer_price_cents fornecido no inventory. price_source informa a origem. So diga \"no catalogo do WhatsApp\" quando price_source comecar com whatsapp_catalog_. So diga \"em promocao\" quando price_source for whatsapp_catalog_sale. NUNCA diga \"conforme o anuncio\" apenas porque o preco veio do catalogo; anuncio e catalogo sao fontes diferentes.","- Resolva referencias como esse Nissan, a Crosser, o segundo, o de 2013 usando recent_catalog e referral. Se houver uma unica correspondencia, responda sobre ela; se houver mais de uma, pergunte qual.","- Nao trate insistencia do cliente corrigindo a IA como loop ou frustracao. Primeiro corrija a interpretacao e responda ao que foi perguntado.","- Em compra e venda simultaneas, reconheca os dois objetivos somente no primeiro turno relevante. Nos seguintes, faca apenas a pergunta necessaria. Nao repita bordoes ou introducoes e nao recapitule modelo e ano a cada turno.","- Quando a pessoa pedir fotos, a entrega depende do backend; nunca afirme que enviou ou que enviara uma imagem antes da confirmacao do provedor.","- A frase automatica Ola! Posso ter mais informacoes sobre isso? deve ser interpretada como consulta contextual a item do catalogo. Use dados de catalog_referral e nao infira qual e o carro sem um vinculo verificavel."].join('\n')}]},contents:[{role:'user',parts:[{text:JSON.stringify({
      official_facts:{business:settings.business_facts,inventory:modelInventory,date:buildDateContext(context),rules:settings.sdr_rules,
        sales_policy:{hot_lead_rule:settings.sales?.hot_lead_rule||'',required_financing_documents:settings.sales?.required_financing_documents||[],conversation_contract:settings.sales?.conversation_contract||{},hot_lead_percent:settings.sdr_rules?.hot_lead_percent??null},referral:referralFacts,
        recent_catalog:recentCatalog.products.map(item=>({id:item.id,name:item.name,model:item.model,brand:item.brand,year:item.year,color:item.color,km:item.km,fuel:item.fuel,price_cents:item.price_cents,price_source:item.price_source||'canonical_inventory',whatsapp_product_id:item.whatsapp_product_id||null,whatsapp_regular_price_cents:item.whatsapp_regular_price_cents||null,whatsapp_sale_price_cents:item.whatsapp_sale_price_cents||null})),
        contextual_reference:contextualReference.product?{status:'unique',vehicle:{id:contextualReference.product.id,name:contextualReference.product.name,model:contextualReference.product.model,brand:contextualReference.product.brand,year:contextualReference.product.year}}:
